/*
 Problem: 4030. Check ASCII Palindromic
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 10.7 MB (11.86%)
 Tags: Two Pointers, String, Bit Manipulation
*/
class Solution {
public:
    bool isPalindromic(string s) {
        string b;
        for (const auto& c : s) b += bitset<8>(c).to_string();
        return b == string(b.rbegin(), b.rend());
    }
};
